import org.apache.commons.lang3.StringUtils;
public class CenterCheck {
    public static void main(String[] args) {
        System.out.println("[" + StringUtils.center("abc", 7, "") + "]");
        System.out.println("[" + StringUtils.center("abc", 7, (String) null) + "]");
        System.out.println("[" + StringUtils.remove("queued", "") + "]");
        System.out.println("[" + StringUtils.remove("queued", (String) null) + "]");
        System.out.println("[" + StringUtils.replaceOnce("aabc", "a", "b") + "]");
        System.out.println("[" + StringUtils.substringBetween("tagfooTagbarTagfoo".toLowerCase(), "tag") + "]");
    }
}
EOF
javac -cp target/classes -d /tmp /tmp/CenterCheck.java && java -cp target/classes:/tmp CenterCheck
